import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt();
        final int NEG = -1000000000;
        // dp[len]: best beauty after keeping a subsequence of length len.
        int[] dp = new int[n + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int t = 0; t < n; t++) {
            int x = nextInt();
            for (int len = n - 1; len >= 0; len--)
                if (dp[len] >= 0) dp[len + 1] = Math.max(dp[len + 1], dp[len] + (x == len + 1 ? 1 : 0));
        }
        int best = NEG;
        for (int len = 1; len <= n; len++) best = Math.max(best, dp[len]);
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := int(nextInt())
	const NEG = -1000000000
	// dp[len]: best beauty after keeping a subsequence of length len.
	dp := make([]int, n+1)
	for i := range dp {
		dp[i] = NEG
	}
	dp[0] = 0
	for t := 0; t < n; t++ {
		x := int(nextInt())
		for l := n - 1; l >= 0; l-- {
			if dp[l] >= 0 {
				gain := 0
				if x == l+1 {
					gain = 1
				}
				dp[l+1] = max(dp[l+1], dp[l]+gain)
			}
		}
	}
	best := NEG
	for l := 1; l <= n; l++ {
		best = max(best, dp[l])
	}
	fmt.Println(best)
}
